 "content": "def transform(grid):
    """Extend the solid color-2 rectangle along its rows and columns.

    Other nonzero colors mark the outward side to leave unextended; a row or
    column with no such marker extends toward both grid edges. Marker cells are
    preserved.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not cells:
        return out
    r0 = min(r for r, _ in cells)
    r1 = max(r for r, _ in cells)
    c0 = min(c for _, c in cells)
    c1 = max(c for _, c in cells)

    # For each row through the rectangle, extend away from any marker outside
    # its left/right edge; with no marker, extend both ways.
    for r in range(r0, r1 + 1):
        left_mark = any(grid[r][c] not in (0, 2) for c in range(c0))
        right_mark = any(grid[r][c] not in (0, 2) for c in range(c1 + 1, w))
        if not left_mark:
            for c in range(c0):
                if out[r][c] == 0:
                    out[r][c] = 2
        if not right_mark:
            for c in range(c1 + 1, w):
                if out[r][c] == 0:
                    out[r][c] = 2

    # For each column through the rectangle, extend away from markers above or
    # below it; with no marker, extend toward both grid edges.
    for c in range(c0, c1 + 1):
        top_mark = any(grid[r][c] not in (0, 2) for r in range(r0))
        bottom_mark = any(grid[r][c] not in (0, 2) for r in range(r1 + 1, h))
        if not top_mark:
            for r in range(r0):
                if out[r][c] == 0:
                    out[r][c] = 2
        if not bottom_mark:
            for r in range(r1 + 1, h):
                if out[r][c] == 0:
                    out[r][c] = 2
    return out
